<?php $this->layout('default'); use Moves\Services\CmsAuth; use Moves\Services\PlatformDirectory; use Moves\Support\CmsView as V;
$d = PlatformDirectory::dashboard();
$section = static fn (string $title, string $link, string $href): string => '<div class="cms-section-head"><h2>' . V::e($title) . '</h2><a href="' . V::e($href) . '">' . V::e($link) . '</a></div>';
$shortcuts = array_filter([['/paginas/novo', 'Nova página', 'pages.manage', true], ['/conteudos/novo', 'Novo conteúdo', 'content.manage', false], ['/midia', 'Enviar mídia', 'media.manage', false], ['/planos', 'Planos e preços', 'plans.view', false], ['/chamados/fila', 'Fila de atendimento', 'tickets.view', false], ['/configuracoes', 'Configurações', 'settings.manage', false]], static fn (array $item): bool => CmsAuth::can($admin, $item[2]));
$this->start('actions'); ?><a class="cms-btn" href="<?= V::e(getenv('APP_URL') ?: '/') ?>" target="_blank" rel="noopener">Visualizar site</a><?php $this->stop(); ?>
<p class="cms-lead">Olá, <?= V::e($admin['first_name']) ?>! Aqui está o resumo da plataforma hoje.</p>
<?php if (CmsAuth::can($admin, 'users.view')): ?><?= $section('Plataforma', 'Ver usuários', '/usuarios') ?><?= V::kpis([['users', 'Usuários', (string) $d['users_total'], 'cadastrados'], ['check', 'Ativos', (string) $d['users_active'], 'usuários ativos'], ['plus', 'Novos', (string) $d['users_new_30'], 'nos últimos 30 dias'], ['building', 'Empresas', (string) $d['companies_total'], 'cadastradas']]) ?><?php endif; ?>
<?php if (CmsAuth::can($admin, 'subscriptions.view')): ?><?= $section('Comercial', 'Ver assinaturas', '/assinaturas') ?><?= V::kpis([['repeat', 'Assinaturas ativas', (string) ($d['subs']['active'] ?? 0), 'contratos vigentes'], ['clock', 'Pendentes', (string) ($d['subs']['pending'] ?? 0), 'aguardando pagamento'], ['alert', 'Canceladas', (string) ($d['subs']['canceled'] ?? 0), 'encerradas'], ['tag', 'Planos contratados', (string) $d['plans_contracted'], 'com assinantes'], ['card', 'Cobranças pendentes', (string) $d['charges_pending'], 'em aberto ou vencidas'], ['chart', 'Receita recorrente', V::money($d['mrr']), 'por mês, assinaturas ativas']]) ?><?php endif; ?>
<?php if (CmsAuth::can($admin, 'tickets.view')): ?><?= $section('Atendimento', 'Abrir fila', '/chamados/fila') ?><?= V::kpis([['chat', 'Abertos', (string) ($d['tickets']['open'] ?? 0), 'chamados novos'], ['clock', 'Pendentes', (string) $d['tickets_pending'], 'aguardando a equipe'], ['chat', 'Em atendimento', (string) ($d['tickets']['in_progress'] ?? 0), 'com responsável agindo'], ['check', 'Resolvidos', (string) (($d['tickets']['resolved'] ?? 0) + ($d['tickets']['closed'] ?? 0)), 'resolvidos ou fechados'], ['clock', 'Primeira resposta', V::minutes($d['first_response_avg']), 'tempo médio'], ['clock', 'Resolução', V::minutes($d['resolution_avg']), 'tempo médio']]) ?><?php endif; ?>
<?php if ($shortcuts !== []): ?><section class="cms-card"><span class="cms-eyebrow">Ações rápidas</span><div class="cms-actions"><?php foreach ($shortcuts as [$href, $label, , $primary]): ?><a class="<?= $primary ? 'cms-btn-primary' : 'cms-btn' ?>" href="<?= V::e($href) ?>"><?= V::e($label) ?></a><?php endforeach; ?></div></section><?php endif; ?>
